def intercalar(a,b):
    out = []; i = j = 0
    while i<len(a) and j<len(b):
        if a[i]<=b[j]: out.append(a[i]); i+=1
        else: out.append(b[j]); j+=1
    return out+a[i:]+b[j:]
def mergesort(a):
    if len(a)<=1: return list(a)
    m=len(a)//2
    return intercalar(mergesort(a[:m]),mergesort(a[m:]))
for entrada in [[],[3,2,1],[2,2,1],[7]]:
    antes=list(entrada)
    assert mergesort(entrada)==sorted(entrada)
